import csv,datetime as d
rows=list(csv.DictReader(open('inputs/shipments.csv')))
on=0;delays={}
for r in rows:
  p=d.date.fromisoformat(r['promised']);q=d.date.fromisoformat(r['delivered'])
  on+= q<=p
  delays.setdefault(r['carrier_code'],[]).append((q-p).days)
print(on,len(rows),round(on/len(rows),4))
for c,v in sorted(delays.items()): print(c,round(sum(v)/len(v),3),len(v))
